### 2. defineEmits 类型标注

```vue
<script setup lang="ts">
interface SearchParams {
  keyword: string
  page: number
  pageSize: number
}

// 泛型语法定义事件类型
const emit = defineEmits<{
  // 事件名: [参数列表]
  change: [value: string]
  search: [params: SearchParams]
  'update:modelValue': [value: string]
  submit: []                         // 无参数事件
  delete: [id: number, reason?: string]  // 可选参数
}>()

function handleSearch() {
  // ✅ 类型安全：参数类型会被检查
  emit('search', {
    keyword: 'vue3',
    page: 1,
    pageSize: 20
  })
}

function handleDelete(id: number) {
  emit('delete', id, '用户主动删除')
}

function handleChange(e: Event) {
  const target = e.target as HTMLInputElement
  emit('change', target.value)
  emit('update:modelValue', target.value)
}
</script>

<template>
  <div>
    <input @input="handleChange" />
    <button @click="handleSearch">搜索</button>
    <button @click="handleDelete(1)">删除</button>
    <button @click="emit('submit')">提交</button>
  </div>
</template>
```

### 3. 提取可复用类型

```typescript
// types/components.ts
export interface PaginationProps {
  page: number
  pageSize: number
  total: number
  pageSizes?: number[]
}

export interface PaginationEmits {
  'update:page': [page: number]
  'update:pageSize': [size: number]
}

// 在组件中引入
// import type { PaginationProps, PaginationEmits } from '@/types/components'
// const props = defineProps<PaginationProps>()
// const emit = defineEmits<PaginationEmits>()
```

**最佳实践总结**：
1. 优先使用泛型语法 `defineProps<{}>()` — 更简洁、更好的类型推导
2. 需要默认值时配合 `withDefaults()` 使用
3. 需要运行时验证（validator）时用 `PropType` 方式
4. 将可复用的类型提取到独立文件（如 `types/components.ts`）
5. `defineEmits` 使用具名元组语法 `[name: Type]` 提升可读性

## axios 统一封装：拦截器 + Token + 错误处理

### request.ts — 请求封装

```typescript
import axios from 'axios'
import type { AxiosInstance, AxiosRequestConfig, AxiosResponse, InternalAxiosRequestConfig } from 'axios'
import { ElMessage, ElLoading } from 'element-plus'
import type { LoadingInstance } from 'element-plus/es/components/loading/src/loading'

// 响应数据的统一格式
interface ApiResponse<T = any> {
  code: number
  data: T
  message: string
}

// 扩展 AxiosRequestConfig，支持自定义选项
interface RequestConfig extends AxiosRequestConfig {
  showLoading?: boolean   // 是否显示全局 loading
  showError?: boolean     // 是否显示错误提示
  retry?: number          // 重试次数
}

let loadingInstance: LoadingInstance | null = null
let loadingCount = 0

function showLoading() {
  if (loadingCount === 0) {
    loadingInstance = ElLoading.service({
      lock: true,
      text: '加载中...',
      background: 'rgba(0, 0, 0, 0.1)'
    })
  }
  loadingCount++
}

function hideLoading() {
  loadingCount--
  if (loadingCount <= 0) {
    loadingCount = 0
    loadingInstance?.close()
    loadingInstance = null
  }
}

// 创建 axios 实例
const service: AxiosInstance = axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL || '/api',
  timeout: 15000,
  headers: {
    'Content-Type': 'application/json'
  }
})

// ========== 请求拦截器 ==========
service.interceptors.request.use(
  (config: InternalAxiosRequestConfig & RequestConfig) => {
    // 1. 注入 Token
    const token = localStorage.getItem('access_token')
    if (token) {
      config.headers.Authorization = `Bearer ${token}`
    }

    // 2. 显示 Loading
    if (config.showLoading !== false) {
      showLoading()
    }

    return config
  },
  (error) => {
    return Promise.reject(error)
  }
)

// ========== 响应拦截器 ==========
service.interceptors.response.use(
  (response: AxiosResponse<ApiResponse>) => {
    const config = response.config as RequestConfig

    // 关闭 Loading
    if (config.showLoading !== false) {
      hideLoading()
    }

    const { code, data, message } = response.data

    // 业务状态码判断
    if (code === 200) {
      return data as any
    }

    // Token 过期
    if (code === 401) {
      localStorage.removeItem('access_token')
      ElMessage.error('登录已过期，请重新登录')
      window.location.href = '/login'
      return Promise.reject(new Error('Token expired'))
    }

    // 其他业务错误
    if (config.showError !== false) {
      ElMessage.error(message || '请求失败')
    }
    return Promise.reject(new Error(message))
  },
  (error) => {
    // 关闭 Loading
    hideLoading()

    // HTTP 错误处理
    const status = error.response?.status
    const errorMap: Record<number, string> = {
      400: '请求参数错误',
      403: '没有访问权限',
      404: '请求资源不存在',
      500: '服务器内部错误',
      502: '网关错误',
      503: '服务不可用'
    }

    const msg = errorMap[status] || error.message || '网络异常'
    ElMessage.error(msg)
    return Promise.reject(error)
  }
)

// ========== 封装请求方法 ==========
export function get<T>(url: string, params?: object, config?: RequestConfig): Promise<T> {
  return service.get(url, { params, ...config })
}

export function post<T>(url: string, data?: object, config?: RequestConfig): Promise<T> {
  return service.post(url, data, config)
}

export function put<T>(url: string, data?: object, config?: RequestConfig): Promise<T> {
  return service.put(url, data, config)
}

export function del<T>(url: string, config?: RequestConfig): Promise<T> {
  return service.delete(url, config)
}

export default service
```

### 使用示例

```typescript
// api/user.ts
import { get, post } from '@/utils/request'

interface User {
  id: number
  name: string
  email: string
}

interface LoginParams {
  username: string
  password: string
}

interface LoginResult {
  token: string
  user: User
}

export const userApi = {
  // 获取用户列表
  getList: (page: number, size: number) =>
    get<{ list: User[]; total: number }>('/users', { page, size }),

  // 登录（不显示全局 loading）
  login: (params: LoginParams) =>
    post<LoginResult>('/auth/login', params, { showLoading: false }),

  // 获取当前用户
  getProfile: () => get<User>('/users/me')
}
```

**要点**：
1. 请求拦截器统一注入 Token，无需在每个 API 手动设置
2. 响应拦截器统一处理业务错误码和 HTTP 错误
3. Loading 使用引用计数，支持并发请求
4. 泛型方法 `get<T>` 返回 `Promise<T>`，调用端自动推导类型

## axios 请求取消与并发管理

### 1. AbortController 取消请求

```vue
<script setup lang="ts">
import { ref, onUnmounted } from 'vue'
import axios from 'axios'

interface SearchResult {
  id: number
  title: string
}

const keyword = ref<string>('')
const results = ref<SearchResult[]>([])
const loading = ref<boolean>(false)

// 保存当前的 AbortController
let currentController: AbortController | null = null

async function search(query: string) {
  // 取消上一次未完成的请求
  if (currentController) {
    currentController.abort()
  }

  if (!query.trim()) {
    results.value = []
    return
  }

  // 创建新的 AbortController
  currentController = new AbortController()
  loading.value = true

  try {
    const response = await axios.get<SearchResult[]>('/api/search', {
      params: { q: query },
      signal: currentController.signal
    })
    results.value = response.data
  } catch (error) {
    if (axios.isCancel(error)) {
      console.log('请求已取消:', query)
      // 取消的请求不需要处理
      return
    }
    console.error('搜索失败:', error)
  } finally {
    loading.value = false
  }
}

// 防抖搜索
let debounceTimer: ReturnType<typeof setTimeout>
function handleInput(e: Event) {
  const value = (e.target as HTMLInputElement).value
  keyword.value = value
  clearTimeout(debounceTimer)
  debounceTimer = setTimeout(() => search(value), 300)
}

// 组件卸载时取消所有请求
onUnmounted(() => {
  currentController?.abort()
  clearTimeout(debounceTimer)
})
</script>

<template>
  <div>
    <input :value="keyword" @input="handleInput" placeholder="输入关键词搜索..." />
    <div v-if="loading">搜索中...</div>
    <ul>
      <li v-for="item in results" :key="item.id">{{ item.title }}</li>
    </ul>
  </div>
</template>
```

### 2. Promise.all 并发请求

```typescript
import axios from 'axios'
import type { AxiosResponse } from 'axios'

interface User { id: number; name: string }
interface Order { id: number; amount: number; status: string }
interface Stats { totalUsers: number; totalOrders: number; revenue: number }

// 方式一：Promise.all — 全部成功或第一个失败
async function fetchDashboardData() {
  try {
    const [usersRes, ordersRes, statsRes] = await Promise.all([
      axios.get<User[]>('/api/users'),
      axios.get<Order[]>('/api/orders'),
      axios.get<Stats>('/api/stats')
    ])

    return {
      users: usersRes.data,
      orders: ordersRes.data,
      stats: statsRes.data
    }
  } catch (error) {
    console.error('其中一个请求失败，全部取消:', error)
    throw error
  }
}

// 方式二：Promise.allSettled — 所有请求完成（无论成败）
async function fetchDashboardSafe() {
  const results = await Promise.allSettled([
    axios.get<User[]>('/api/users'),
    axios.get<Order[]>('/api/orders'),
    axios.get<Stats>('/api/stats')
  ])

  return {
    users: results[0].status === 'fulfilled' ? results[0].value.data : [],
    orders: results[1].status === 'fulfilled' ? results[1].value.data : [],
    stats: results[2].status === 'fulfilled' ? results[2].value.data : null
  }
}

// 方式三：带超时和取消的并发请求
async function fetchWithTimeout(timeout: number = 5000) {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), timeout)

  try {
    const [users, orders] = await Promise.all([
      axios.get<User[]>('/api/users', { signal: controller.signal }),
      axios.get<Order[]>('/api/orders', { signal: controller.signal })
    ])
    return { users: users.data, orders: orders.data }
  } catch (error) {
    if (axios.isCancel(error)) {
      throw new Error(`请求超时 (${timeout}ms)`)
    }
    throw error
  } finally {
    clearTimeout(timer)
  }
}
```

**要点**：
1. `AbortController` 替代已废弃的 `CancelToken`
2. 搜索场景：每次新请求前取消上一次未完成的请求，避免竞态
3. `Promise.all` 任一失败则全部拒绝；`Promise.allSettled` 等待全部完成
4. 组件卸载时必须取消请求，防止更新已销毁组件的状态

## CSS Flex 布局核心概念

Flex 布局由**容器**（flex container）和**子项**（flex item）组成，通过主轴和交叉轴控制排列方式。

### 核心属性速查

| 容器属性 | 作用 | 常用值 |
|---------|------|--------|
| `display` | 启用 flex | `flex` / `inline-flex` |
| `flex-direction` | 主轴方向 | `row` / `column` |
| `justify-content` | 主轴对齐 | `flex-start` / `center` / `space-between` / `space-around` |
| `align-items` | 交叉轴对齐 | `stretch` / `center` / `flex-start` / `flex-end` |
| `flex-wrap` | 换行 | `nowrap` / `wrap` |
| `gap` | 间距 | `8px` / `8px 16px` |

| 子项属性 | 作用 | 常用值 |
|---------|------|--------|
| `flex-grow` | 放大比例 | `0`（默认）/ `1` |
| `flex-shrink` | 缩小比例 | `1`（默认）/ `0` |
| `flex-basis` | 初始大小 | `auto` / `200px` / `0` |
| `flex` | 简写 | `1`=`1 1 0` / `auto`=`1 1 auto` / `none`=`0 0 auto` |
| `align-self` | 单独对齐 | 覆盖容器的 `align-items` |

### 典型布局示例

```css
/* 1. 经典导航栏：logo 左 + 菜单中 + 操作按钮右 */
.navbar {
  display: flex;
  align-items: center;
  padding: 0 24px;
  height: 60px;
  background: #fff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
}
.navbar .logo {
  flex-shrink: 0;         /* logo 不被压缩 */
  width: 120px;
}
.navbar .menu {
  flex: 1;                /* 占据剩余空间 */
  display: flex;
  justify-content: center;
  gap: 24px;
}
.navbar .actions {
  flex-shrink: 0;
  display: flex;
  gap: 12px;
}

/* 2. 卡片网格：自动换行 + 等间距 */
.card-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}
.card-grid .card {
  flex: 0 0 calc(33.333% - 11px);  /* 每行 3 个，扣除 gap */
  border: 1px solid #e4e7ed;
  border-radius: 8px;
  padding: 16px;
}

/* 3. 圣杯布局：header + (sidebar + main + aside) + footer */
.holy-grail {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}
.holy-grail .header,
.holy-grail .footer {
  flex-shrink: 0;
  height: 60px;
  background: #f5f7fa;
}
.holy-grail .body {
  flex: 1;
  display: flex;
}
.holy-grail .sidebar {
  flex: 0 0 220px;        /* 固定宽度不伸缩 */
  background: #fafafa;
}
.holy-grail .main {
  flex: 1;                /* 自适应中间区域 */
  padding: 24px;
}
.holy-grail .aside {
  flex: 0 0 200px;
  background: #fafafa;
}

/* 4. 垂直水平居中 */
