## Pinia 状态管理 — 两种 Store 定义方式

Pinia 是 Vue3 官方推荐的状态管理库，支持两种定义风格。

### 1. Options Store（Options API 风格）

```typescript
// stores/useCounterStore.ts
import { defineStore } from 'pinia'

export const useCounterStore = defineStore('counter', {
  // state：返回一个函数
  state: () => ({
    count: 0,
    name: 'Counter Store'
  }),

  // getters：类似 computed
  getters: {
    doubleCount: (state) => state.count * 2,
    // getter 中访问其他 getter
    displayText(): string {
      return `${this.name}: ${this.doubleCount}`
    }
  },

  // actions：支持同步和异步
  actions: {
    increment() {
      this.count++
    },
    async fetchCount() {
      const res = await fetch('/api/count')
      const data = await res.json()
      this.count = data.count
    }
  }
})
```

### 2. Setup Store（Composition API 风格，推荐）

```typescript
// stores/useUserStore.ts
import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { get, post } from '@/utils/request'

interface User {
  id: number
  name: string
  avatar: string
  role: string
}

export const useUserStore = defineStore('user', () => {
  // state → ref / reactive
  const token = ref<string>(localStorage.getItem('token') || '')
  const userInfo = ref<User | null>(null)
  const loading = ref<boolean>(false)

  // getters → computed
  const isLoggedIn = computed<boolean>(() => !!token.value)
  const userName = computed<string>(() => userInfo.value?.name || '未登录')
  const isAdmin = computed<boolean>(() => userInfo.value?.role === 'admin')

  // actions → function
  async function login(username: string, password: string) {
    loading.value = true
    try {
      const data = await post<{ token: string; user: User }>('/auth/login', {
        username,
        password
      })
      token.value = data.token
      userInfo.value = data.user
      localStorage.setItem('token', data.token)
    } finally {
      loading.value = false
    }
  }

  function logout() {
    token.value = ''
    userInfo.value = null
    localStorage.removeItem('token')
  }

  async function fetchUserInfo() {
    if (!token.value) return
    userInfo.value = await get<User>('/users/me')
  }

  // 必须 return 所有需要暴露的状态和方法
  return {
    token,
    userInfo,
    loading,
    isLoggedIn,
    userName,
    isAdmin,
    login,
    logout,
    fetchUserInfo
  }
})
```

### 3. 在组件中使用

```vue
<script setup lang="ts">
import { storeToRefs } from 'pinia'
import { useUserStore } from '@/stores/useUserStore'
import { useCounterStore } from '@/stores/useCounterStore'

const userStore = useUserStore()
const counterStore = useCounterStore()

// ⚠️ 解构时必须用 storeToRefs 保持响应性
const { userName, isLoggedIn, loading } = storeToRefs(userStore)
const { count, doubleCount } = storeToRefs(counterStore)

// actions 可以直接解构（不需要 storeToRefs）
const { login, logout } = userStore
const { increment } = counterStore
</script>

<template>
  <div>
    <p>用户: {{ userName }}</p>
    <p>计数: {{ count }} (双倍: {{ doubleCount }})</p>
    <button @click="increment">+1</button>
    <button v-if="isLoggedIn" @click="logout">退出</button>
  </div>
</template>
```

**要点**：
1. Setup Store 更灵活，能直接使用 composables 和 Vue 的响应式 API
2. `storeToRefs()` 解构 state 和 getters 保持响应性；actions 直接解构
3. Options Store 中 `this` 指向 store 实例；Setup Store 中无 `this`
4. Store 命名建议 `use___Store` 格式，Store ID 使用小写

## Pinia 持久化 + 模块化

### 1. Pinia 持久化插件配置

```typescript
// plugins/pinia-persist.ts
import type { PiniaPluginContext } from 'pinia'
import { watch } from 'vue'

interface PersistOptions {
  key?: string
  paths?: string[]           // 只持久化指定字段
  storage?: Storage          // 默认 localStorage
  beforeRestore?: (ctx: PiniaPluginContext) => void
}

// 声明扩展 Pinia 的类型
declare module 'pinia' {
  export interface DefineStoreOptionsBase<S, Store> {
    persist?: PersistOptions | boolean
  }
}

export function piniaPersistedState({ store, options }: PiniaPluginContext) {
  const persistOptions = options.persist
  if (!persistOptions) return

  const config: PersistOptions = typeof persistOptions === 'boolean'
    ? {}
    : persistOptions

  const key = config.key || `pinia_${store.$id}`
  const storage = config.storage || localStorage

  // 恢复状态
  const savedState = storage.getItem(key)
  if (savedState) {
    try {
      const parsed = JSON.parse(savedState)
      store.$patch(parsed)
    } catch (e) {
      console.warn(`[Pinia Persist] Failed to restore ${key}:`, e)
    }
  }

  // 监听变化并持久化
  watch(
    () => {
      if (config.paths) {
        // 只持久化指定路径
        const partial: Record<string, any> = {}
        for (const path of config.paths) {
          partial[path] = (store.$state as any)[path]
        }
        return JSON.stringify(partial)
      }
      return JSON.stringify(store.$state)
    },
    (newVal) => {
      storage.setItem(key, newVal)
    },
    { deep: true }
  )
}

// main.ts 中注册
// import { createPinia } from 'pinia'
// import { piniaPersistedState } from './plugins/pinia-persist'
// const pinia = createPinia()
// pinia.use(piniaPersistedState)
```

### 2. 模块化 Store 定义

```typescript
// stores/useAuthStore.ts — 认证 Store
import { defineStore } from 'pinia'
import { ref, computed } from 'vue'

export const useAuthStore = defineStore('auth', () => {
  const token = ref<string>('')
  const refreshToken = ref<string>('')

  const isAuthenticated = computed(() => !!token.value)

  function setTokens(access: string, refresh: string) {
    token.value = access
    refreshToken.value = refresh
  }

  function clearTokens() {
    token.value = ''
    refreshToken.value = ''
  }

  return { token, refreshToken, isAuthenticated, setTokens, clearTokens }
}, {
  // 持久化配置：只保存 token 相关字段
  persist: {
    paths: ['token', 'refreshToken']
  }
})
```

```typescript
// stores/useUserStore.ts — 用户 Store，引用 Auth Store
import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { useAuthStore } from './useAuthStore'
import { get } from '@/utils/request'

interface User {
  id: number
  name: string
  role: string
  permissions: string[]
}

export const useUserStore = defineStore('user', () => {
  // ✅ 在 Setup Store 中可以直接引用其他 Store
  const authStore = useAuthStore()

  const userInfo = ref<User | null>(null)

  const userName = computed(() => userInfo.value?.name || '游客')
  const hasPermission = computed(() => {
    return (perm: string) => userInfo.value?.permissions.includes(perm) ?? false
  })

  async function fetchUser() {
    if (!authStore.isAuthenticated) return
    userInfo.value = await get<User>('/users/me')
  }

  function logout() {
    userInfo.value = null
    authStore.clearTokens()  // 调用其他 store 的 action
  }

  return { userInfo, userName, hasPermission, fetchUser, logout }
}, {
  persist: {
    paths: ['userInfo']  // 只持久化用户信息
  }
})
```

```typescript
// stores/useSettingsStore.ts — 设置 Store
import { defineStore } from 'pinia'
import { ref, watch } from 'vue'

type ThemeMode = 'light' | 'dark' | 'auto'
type Language = 'zh-CN' | 'en-US'

export const useSettingsStore = defineStore('settings', () => {
  const theme = ref<ThemeMode>('light')
  const language = ref<Language>('zh-CN')
  const sidebarCollapsed = ref<boolean>(false)

  // 监听主题变化，同步 DOM
  watch(theme, (mode) => {
    document.documentElement.setAttribute('data-theme', mode)
  }, { immediate: true })

  function toggleSidebar() {
    sidebarCollapsed.value = !sidebarCollapsed.value
  }

  return { theme, language, sidebarCollapsed, toggleSidebar }
}, {
  persist: true  // 全部字段持久化
})
```

### 3. Store 统一导出

```typescript
// stores/index.ts
export { useAuthStore } from './useAuthStore'
export { useUserStore } from './useUserStore'
export { useSettingsStore } from './useSettingsStore'
```

**要点**：
1. 持久化插件通过 `watch` + `$patch` 实现状态的保存与恢复
2. `paths` 选项控制只持久化指定字段，避免敏感数据或过大状态存入 Storage
3. Setup Store 中可通过直接调用其他 `useXxxStore()` 实现跨 Store 引用
4. 模块化拆分：按功能域拆分 store（auth / user / settings）
5. ⚠️ 避免循环引用：Store A 引用 Store B 时，Store B 不应再引用 Store A

