### 2. 路由实例 + 全局守卫

```typescript
// router/index.ts
import { createRouter, createWebHistory } from 'vue-router'
import type { RouteRecordRaw } from 'vue-router'
import { publicRoutes, asyncRoutes, fallbackRoute } from './routes'
import { useAuthStore } from '@/stores/useAuthStore'
import { useUserStore } from '@/stores/useUserStore'
import NProgress from 'nprogress'
import 'nprogress/nprogress.css'

NProgress.configure({ showSpinner: false })

// 白名单路由
const whiteList = ['/login', '/404']

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes: publicRoutes,
  scrollBehavior(_to, _from, savedPosition) {
    return savedPosition || { top: 0 }
  }
})

// 记录是否已动态添加路由
let hasAddedRoutes = false

// 根据角色过滤路由
function filterRoutesByRole(routes: RouteRecordRaw[], role: string): RouteRecordRaw[] {
  return routes.filter(route => {
    const roles = route.meta?.roles as string[] | undefined
    if (!roles) return true
    if (!roles.includes(role)) return false

    // 递归过滤子路由
    if (route.children) {
      route.children = filterRoutesByRole(route.children, role)
    }
    return true
  })
}

// ========== 全局前置守卫 ==========
router.beforeEach(async (to, from, next) => {
  NProgress.start()
  document.title = `${to.meta.title || ''} - ${import.meta.env.VITE_APP_TITLE}`

  const authStore = useAuthStore()
  const userStore = useUserStore()

  // 1. 已登录用户访问登录页 → 跳转首页
  if (to.path === '/login' && authStore.isAuthenticated) {
    next({ path: '/' })
    return
  }

  // 2. 白名单路由直接放行
  if (whiteList.includes(to.path)) {
    next()
    return
  }

  // 3. 未登录 → 跳转登录页
  if (!authStore.isAuthenticated) {
    next({ path: '/login', query: { redirect: to.fullPath } })
    return
  }

  // 4. 已登录但未加载用户信息 → 获取用户信息 + 动态添加路由
  if (!hasAddedRoutes) {
    try {
      await userStore.fetchUser()
      const role = userStore.userInfo?.role || 'viewer'
      const filteredRoutes = filterRoutesByRole(
        JSON.parse(JSON.stringify(asyncRoutes)),
        role
      )

      // 动态添加路由
      filteredRoutes.forEach(route => router.addRoute(route))
      router.addRoute(fallbackRoute)
      hasAddedRoutes = true

      // 重新导航到目标路由（确保新路由已注册）
      next({ ...to, replace: true })
    } catch (error) {
      authStore.clearTokens()
      next({ path: '/login' })
    }
    return
  }

  // 5. 正常放行
  next()
})

// ========== 全局后置守卫 ==========
router.afterEach(() => {
  NProgress.done()
})

export default router
```

### 3. 页面过渡动画

```vue
<!-- layout/Layout.vue -->
<script setup lang="ts">
import { useRoute } from 'vue-router'
const route = useRoute()
</script>

<template>
  <div class="layout">
    <aside class="sidebar">侧边栏</aside>
    <main class="main-content">
      <router-view v-slot="{ Component, route: currentRoute }">
        <transition :name="(currentRoute.meta.transition as string) || 'fade'" mode="out-in">
          <keep-alive :include="['Dashboard']">
            <component :is="Component" :key="currentRoute.path" />
          </keep-alive>
        </transition>
      </router-view>
    </main>
  </div>
</template>

<style>
/* 渐变 */
.fade-enter-active, .fade-leave-active {
  transition: opacity 0.3s ease;
}
.fade-enter-from, .fade-leave-to {
  opacity: 0;
}

/* 渐变 + 滑动 */
.fade-slide-enter-active, .fade-slide-leave-active {
  transition: all 0.3s ease;
}
.fade-slide-enter-from {
  opacity: 0;
  transform: translateX(20px);
}
.fade-slide-leave-to {
  opacity: 0;
  transform: translateX(-20px);
}
</style>
```

**关键点**：
1. **路由懒加载**：`() => import(...)` 实现按需加载，每个页面独立 chunk
2. **路由元信息 meta**：存放 title、roles、transition 等自定义数据
3. **动态路由**：`router.addRoute()` 根据用户角色动态注册路由
4. **守卫流程**：白名单检查 → 登录检查 → 用户信息加载 → 权限路由注册
5. **过渡动画**：`<router-view>` 的 `v-slot` + `<transition>` 实现路由级别动画
6. **keep-alive**：通过 `include` 缓存指定组件，避免重复渲染
